import sys,collections,heapq,itertools,functools,bisect
def solve(data):
    s=data.strip();n=len(s);d=[0]*n
    for i in range(n-2,-1,-1):
        prev=0
        for j in range(i+1,n):
            old=d[j];d[j]=prev if s[i]==s[j] else 1+min(d[j],d[j-1]);prev=old
    return d[-1]

if __name__=="__main__":
    a=solve(sys.stdin.buffer.read().decode())
    print(" ".join(map(str,a)) if isinstance(a,(list,tuple)) else a)
